WITH cleaned AS (SELECT id, channel, promo_code, starts_on, ends_on, ADD_MONTHS(ends_on, 1) AS ends_on_plus_months, LAST_DAY(ends_on) AS ends_on_month_end, COALESCE(channel, 'OTHER') AS resolved_channel FROM promotions WHERE starts_on > TO_DATE('2023-05-02') AND channel IS NOT NULL) SELECT promo_code FROM cleaned EXCEPT DISTINCT SELECT promo_code FROM promotions WHERE discount_pct < 0.15
